{
  "county_id": "HVA15",
  "actions": [
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical cancer screening.",
      "rationale": "Cervical screening participation in Central Finland wellbeing services county is 70% (three-year mean to 2024) against the national value of 73.4% and the 80% target, and the portfolio models a gain of 1.5-4.5 percentage points for this county.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders to colorectal cancer screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Central Finland wellbeing services county is 78% against the 80% target, and the portfolio models a gain of 1.5-1.97 percentage points for this county.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "The brief states that time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer, so the Goal 3 indicator cannot be checked from open data, and this is the first step recommended for every county.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a guaranteed mortality reduction from these actions: the self-sampling Finnish gain over a reminder letter is about 3 points, far smaller than the international pooled estimate, no Finnish effect size exists for colorectal screening reminders, and the pathway-timestamps action models no health effect because it is the measurement that makes other actions accountable."
}

